if.if:
and mn.Finish_Time_Finish is not null
and (
(mn.Complete_Time_Schedule is not null and TO_CHAR(mn.Complete_Time_Schedule, 'YYYY') > #{params.icmReportingYear}
and TO_CHAR(LAST_DAY(mn.Complete_Time_Finish), 'YYYY-MM-DD') = #{lastDayOfMonth})
or
(mn.Complete_Records_Time_Schedule is not null and TO_CHAR(mn.Complete_Records_Time_Schedule, 'YYYY') > #{params.icmReportingYear}
and TO_CHAR(LAST_DAY(mn.Complete_Records_Time_Finish), 'YYYY-MM-DD') = #{lastDayOfMonth})
or
(mn.P_Remove_Time_Schedule is not null and TO_CHAR(mn.P_Remove_Time_Schedule, 'YYYY') > #{params.icmReportingYear}
and TO_CHAR(LAST_DAY(mn.P_Remove_Time_Finish), 'YYYY-MM-DD') = #{lastDayOfMonth})
or
(mn.Account_Reply_Time_Schedule is not null and TO_CHAR(mn.Account_Reply_Time_Schedule, 'YYYY') > #{params.icmReportingYear}
and TO_CHAR(LAST_DAY(mn.Account_Reply_Time_Finish), 'YYYY-MM-DD') = #{lastDayOfMonth})
)

and mn.Finish_Time_Finish is not null
and (
(mn.Complete_Time_Schedule is not null and YEAR(mn.Complete_Time_Schedule) > #{params.icmReportingYear}
and LAST_DAY(DATE_FORMAT(mn.Complete_Time_Finish, '%Y-%m-%d')) = #{lastDayOfMonth})
or
(mn.Complete_Records_Time_Schedule is not null and YEAR(mn.Complete_Records_Time_Schedule) > #{params.icmReportingYear}
and LAST_DAY(DATE_FORMAT(mn.Complete_Records_Time_Finish, '%Y-%m-%d')) = #{lastDayOfMonth})
or
(mn.P_Remove_Time_Schedule is not null and YEAR(mn.P_Remove_Time_Schedule) > #{params.icmReportingYear}
and LAST_DAY(DATE_FORMAT(mn.P_Remove_Time_Finish, '%Y-%m-%d')) = #{lastDayOfMonth})
or
(mn.Account_Reply_Time_Schedule is not null and YEAR(mn.Account_Reply_Time_Schedule) > #{params.icmReportingYear}
and LAST_DAY(DATE_FORMAT(mn.Account_Reply_Time_Finish, '%Y-%m-%d')) = #{lastDayOfMonth})
)

mapper.select:
        SELECT
        SUM(CASE WHEN mn.Complete_Time_Finish IS NOT NULL
        AND MONTH(mn.Complete_Time_Finish) >= '1'
        AND MONTH(mn.Complete_Time_Finish) <= #{request.month}
        AND YEAR(mn.Complete_Time_Finish) = #{request.year}
        THEN 1 ELSE 0 END) AS completeFinishNum,
        SUM(CASE WHEN (mn.Complete_Time_Status = '05' OR mn.Complete_Time_Status = '03')
        AND MONTH(mn.Complete_Time_Schedule) BETWEEN 1 AND #{request.month}
        AND YEAR(mn.Complete_Time_Schedule) = #{request.year}
        THEN 1 ELSE 0 END) AS completeOutTimeNum,
        SUM(
        CASE WHEN mn.Complete_Time_Finish IS NOT NULL
        AND MONTH(mn.Complete_Time_Finish) >= '1'
        AND MONTH(mn.Complete_Time_Finish) <= #{request.month}
        AND YEAR(mn.Complete_Time_Finish) = #{request.year}
        AND YEAR(mn.Complete_Time_Schedule) > YEAR(mn.Complete_Time_Finish)
        THEN 1 ELSE 0 END
        ) AS completeOutPlanNum,
        SUM(
        CASE WHEN mn.Complete_Time_Schedule IS NOT NULL
        AND MONTH(mn.Complete_Time_Schedule) >= '1'
        AND MONTH(mn.Complete_Time_Schedule) <= #{request.month}
        AND YEAR(mn.Complete_Time_Schedule) = #{request.year}
        THEN 1 ELSE 0 END
        ) AS completeNeedFinishNum,

        SUM(CASE WHEN mn.Complete_Records_Time_Finish IS NOT NULL
        AND MONTH(mn.Complete_Records_Time_Finish) >= '1'
        AND MONTH(mn.Complete_Records_Time_Finish) <= #{request.month}
        AND YEAR(mn.Complete_Records_Time_Finish) = #{request.year}
        THEN 1 ELSE 0 END) AS completeRecordsFinishNum,
        SUM(CASE WHEN (mn.Complete_Records_Time_Status = '05' OR mn.Complete_Records_Time_Status = '03')
        AND MONTH(mn.Complete_Records_Time_Schedule) BETWEEN 1 AND #{request.month}
        AND YEAR(mn.Complete_Records_Time_Schedule) = #{request.year}
        THEN 1 ELSE 0 END) AS completeRecordsOutTimeNum,
        SUM(
        CASE WHEN mn.Complete_Records_Time_Finish IS NOT NULL
        AND MONTH(mn.Complete_Records_Time_Finish) >= '1'
        AND MONTH(mn.Complete_Records_Time_Finish) <= #{request.month}
        AND YEAR(mn.Complete_Records_Time_Finish) = #{request.year}
        AND YEAR(mn.Complete_Records_Time_Schedule) > YEAR(mn.Complete_Records_Time_Finish)
        THEN 1 ELSE 0 END
        ) AS completeRecordsOutPlanNum,
        SUM(
        CASE WHEN mn.Complete_Records_Time_Schedule IS NOT NULL
        AND MONTH(mn.Complete_Records_Time_Schedule) >= '1'
        AND MONTH(mn.Complete_Records_Time_Schedule) <= #{request.month}
        AND YEAR(mn.Complete_Records_Time_Schedule) = #{request.year}
        THEN 1 ELSE 0 END
        )AS completeRecordsNeedFinishNum,

        SUM(CASE WHEN mn.P_Remove_Time_Finish IS NOT NULL
        AND MONTH(mn.P_Remove_Time_Finish) >= '1'
        AND MONTH(mn.P_Remove_Time_Finish) <= #{request.month}
        AND YEAR(mn.P_Remove_Time_Finish) = #{request.year}
        THEN 1 ELSE 0 END) AS pRemoveFinishNum,
        SUM(CASE WHEN (mn.P_Remove_Time_Status = '05' OR mn.P_Remove_Time_Status = '03')
        AND MONTH(mn.P_Remove_Time_Schedule) BETWEEN 1 AND #{request.month}
        AND YEAR(mn.P_Remove_Time_Schedule) = #{request.year}
        THEN 1 ELSE 0 END) AS pRemoveOutTimeNum,
        SUM(
        CASE WHEN mn.P_Remove_Time_Finish IS NOT NULL
        AND MONTH(mn.P_Remove_Time_Finish) >= '1'
        AND MONTH(mn.P_Remove_Time_Finish) <= #{request.month}
        AND YEAR(mn.P_Remove_Time_Finish) = #{request.year}
        AND YEAR(mn.P_Remove_Time_Schedule) > YEAR(mn.P_Remove_Time_Finish)
        THEN 1 ELSE 0 END
        ) AS pRemoveOutPlanNum,
        SUM(
        CASE WHEN mn.P_Remove_Time_Schedule IS NOT NULL
        AND MONTH(mn.P_Remove_Time_Schedule) >= '1'
        AND MONTH(mn.P_Remove_Time_Schedule) <= #{request.month}
        AND YEAR(mn.P_Remove_Time_Schedule) = #{request.year}
        THEN 1 ELSE 0 END
        ) AS pRemoveNeedFinishNum,

        SUM(CASE WHEN mn.Account_Submit_Time_Finish IS NOT NULL
        AND MONTH(mn.Account_Submit_Time_Finish) >= '1'
        AND MONTH(mn.Account_Submit_Time_Finish) <= #{request.month}
        AND YEAR(mn.Account_Submit_Time_Finish) = #{request.year}
        THEN 1 ELSE 0 END) AS accountSubmitFinishNum,
        SUM(CASE WHEN (mn.Account_Submit_Time_Status = '05' OR mn.Account_Submit_Time_Status = '03')
        AND MONTH(mn.Account_Submit_Time_Schedule) BETWEEN 1 AND #{request.month}
        AND YEAR(mn.Account_Submit_Time_Schedule) = #{request.year}
        THEN 1 ELSE 0 END) AS accountSubmitOutTimeNum,
        SUM(
        CASE WHEN mn.Account_Submit_Time_Finish IS NOT NULL
        AND MONTH(mn.Account_Submit_Time_Finish) >= '1'
        AND MONTH(mn.Account_Submit_Time_Finish) <= #{request.month}
        AND YEAR(mn.Account_Submit_Time_Finish) = #{request.year}
        AND YEAR(mn.Account_Submit_Time_Schedule) > YEAR(mn.Account_Submit_Time_Finish)
        THEN 1 ELSE 0 END
        ) AS accountSubmitOutPlanNum,
        SUM(
        CASE WHEN mn.Account_Submit_Time_Schedule IS NOT NULL
        AND MONTH(mn.Account_Submit_Time_Schedule) >= '1'
        AND MONTH(mn.Account_Submit_Time_Schedule) <= #{request.month}
        AND YEAR(mn.Account_Submit_Time_Schedule) = #{request.year}
        THEN 1 ELSE 0 END
        ) AS accountSubmitNeedFinishNum
        FROM (SELECT *
        FROM gantt_milestone_statistics mn
        where mn.Complete_Time_Finish = (SELECT MAX(mn2.Complete_Time_Finish)
        FROM gantt_milestone_statistics mn2
        where mn2.p_id = mn.p_id)
        ) mn
        ${authSql}

        SELECT
        SUM(CASE WHEN mn.Complete_Time_Finish IS NOT NULL
        AND EXTRACT(MONTH FROM mn.Complete_Time_Finish) >= 1
        AND EXTRACT(MONTH FROM mn.Complete_Time_Finish) <= #{request.month}
        AND EXTRACT(YEAR FROM mn.Complete_Time_Finish) = #{request.year}
        THEN 1 ELSE 0 END) AS completeFinishNum,
        SUM(CASE WHEN (mn.Complete_Time_Status = '05' OR mn.Complete_Time_Status = '03')
        AND EXTRACT(YEAR FROM mn.Complete_Time_Schedule) = #{request.year}
        THEN 1 ELSE 0 END) AS completeOutTimeNum,
        SUM(
        CASE WHEN mn.Complete_Time_Finish IS NOT NULL
        AND EXTRACT(MONTH FROM mn.Complete_Time_Finish) >= 1
        AND EXTRACT(MONTH FROM mn.Complete_Time_Finish) <= #{request.month}
        AND EXTRACT(YEAR FROM mn.Complete_Time_Finish) = #{request.year}
        AND EXTRACT(YEAR FROM mn.Complete_Time_Schedule) > EXTRACT(YEAR FROM mn.Complete_Time_Finish)
        THEN 1 ELSE 0 END
        ) AS completeOutPlanNum,
        SUM(
        CASE WHEN mn.Complete_Time_Schedule IS NOT NULL
        AND EXTRACT(MONTH FROM mn.Complete_Time_Schedule) >= 1
        AND EXTRACT(MONTH FROM mn.Complete_Time_Schedule) <= #{request.month}
        AND EXTRACT(YEAR FROM mn.Complete_Time_Schedule) = #{request.year}
        THEN 1 ELSE 0 END
        ) AS completeNeedFinishNum,

        SUM(CASE WHEN mn.Complete_Records_Time_Finish IS NOT NULL
        AND EXTRACT(MONTH FROM mn.Complete_Records_Time_Finish) >= 1
        AND EXTRACT(MONTH FROM mn.Complete_Records_Time_Finish) <= #{request.month}
        AND EXTRACT(YEAR FROM mn.Complete_Records_Time_Finish) = #{request.year}
        THEN 1 ELSE 0 END) AS completeRecordsFinishNum,
        SUM(CASE WHEN (mn.Complete_Records_Time_Status = '05' OR mn.Complete_Records_Time_Status = '03')
        AND EXTRACT(YEAR FROM mn.Complete_Records_Time_Schedule) = #{request.year}
        THEN 1 ELSE 0 END) AS completeRecordsOutTimeNum,
        SUM(
        CASE WHEN mn.Complete_Records_Time_Finish IS NOT NULL
        AND EXTRACT(MONTH FROM mn.Complete_Records_Time_Finish) >= 1
        AND EXTRACT(MONTH FROM mn.Complete_Records_Time_Finish) <= #{request.month}
        AND EXTRACT(YEAR FROM mn.Complete_Records_Time_Finish) = #{request.year}
        AND EXTRACT(YEAR FROM mn.Complete_Records_Time_Schedule) > EXTRACT(YEAR FROM mn.Complete_Records_Time_Finish)
        THEN 1 ELSE 0 END
        ) AS completeRecordsOutPlanNum,
        SUM(
        CASE WHEN mn.Complete_Records_Time_Schedule IS NOT NULL
        AND EXTRACT(MONTH FROM mn.Complete_Records_Time_Schedule) >= 1
        AND EXTRACT(MONTH FROM mn.Complete_Records_Time_Schedule) <= #{request.month}
        AND EXTRACT(YEAR FROM mn.Complete_Records_Time_Schedule) = #{request.year}
        THEN 1 ELSE 0 END
        )AS completeRecordsNeedFinishNum,

        SUM(CASE WHEN mn.P_Remove_Time_Finish IS NOT NULL
        AND EXTRACT(MONTH FROM mn.P_Remove_Time_Finish) >= 1
        AND EXTRACT(MONTH FROM mn.P_Remove_Time_Finish) <= #{request.month}
        AND EXTRACT(YEAR FROM mn.P_Remove_Time_Finish) = #{request.year}
        THEN 1 ELSE 0 END) AS pRemoveFinishNum,
        SUM(CASE WHEN (mn.P_Remove_Time_Status = '05' OR mn.P_Remove_Time_Status = '03')
        AND EXTRACT(YEAR FROM mn.P_Remove_Time_Schedule) = #{request.year}
        THEN 1 ELSE 0 END) AS pRemoveOutTimeNum,
        SUM(
        CASE WHEN mn.P_Remove_Time_Finish IS NOT NULL
        AND EXTRACT(MONTH FROM mn.P_Remove_Time_Finish) >= 1
        AND EXTRACT(MONTH FROM mn.P_Remove_Time_Finish) <= #{request.month}
        AND EXTRACT(YEAR FROM mn.P_Remove_Time_Finish) = #{request.year}
        AND EXTRACT(YEAR FROM mn.P_Remove_Time_Schedule) > EXTRACT(YEAR FROM mn.P_Remove_Time_Finish)
        THEN 1 ELSE 0 END
        ) AS pRemoveOutPlanNum,
        SUM(
        CASE WHEN mn.P_Remove_Time_Schedule IS NOT NULL
        AND EXTRACT(MONTH FROM mn.P_Remove_Time_Schedule) >= 1
        AND EXTRACT(MONTH FROM mn.P_Remove_Time_Schedule) <= #{request.month}
        AND EXTRACT(YEAR FROM mn.P_Remove_Time_Schedule) = #{request.year}
        THEN 1 ELSE 0 END
        ) AS pRemoveNeedFinishNum,

        SUM(CASE WHEN mn.Account_Submit_Time_Finish IS NOT NULL
        AND EXTRACT(MONTH FROM mn.Account_Submit_Time_Finish) >= 1
        AND EXTRACT(MONTH FROM mn.Account_Submit_Time_Finish) <= #{request.month}
        AND EXTRACT(YEAR FROM mn.Account_Submit_Time_Finish) = #{request.year}
        THEN 1 ELSE 0 END) AS accountSubmitFinishNum,
        SUM(CASE WHEN (mn.Account_Submit_Time_Status = '05' OR mn.Account_Submit_Time_Status = '03')
        AND EXTRACT(YEAR FROM mn.Account_Submit_Time_Schedule) = #{request.year}
        THEN 1 ELSE 0 END) AS accountSubmitOutTimeNum,
        SUM(
        CASE WHEN mn.Account_Submit_Time_Finish IS NOT NULL
        AND EXTRACT(MONTH FROM mn.Account_Submit_Time_Finish) >= 1
        AND EXTRACT(MONTH FROM mn.Account_Submit_Time_Finish) <= #{request.month}
        AND EXTRACT(YEAR FROM mn.Account_Submit_Time_Finish) = #{request.year}
        AND EXTRACT(YEAR FROM mn.Account_Submit_Time_Schedule) > EXTRACT(YEAR FROM mn.Account_Submit_Time_Finish)
        THEN 1 ELSE 0 END
        ) AS accountSubmitOutPlanNum,
        SUM(
        CASE WHEN mn.Account_Submit_Time_Schedule IS NOT NULL
        AND EXTRACT(MONTH FROM mn.Account_Submit_Time_Schedule) >= 1
        AND EXTRACT(MONTH FROM mn.Account_Submit_Time_Schedule) <= #{request.month}
        AND EXTRACT(YEAR FROM mn.Account_Submit_Time_Schedule) = #{request.year}
        THEN 1 ELSE 0 END
        ) AS accountSubmitNeedFinishNum
        FROM (SELECT *
        FROM (SELECT *,
        ROW_NUMBER() OVER (PARTITION BY mn.p_id ORDER BY mn.Complete_Time_Finish DESC) AS rn
        FROM gantt_milestone_statistics mn) t
        WHERE t.rn = 1) mn
        ${authSql}

SELECT sd.D_Name AS competentDepartmentName,
'年度计划' AS type,
SUM(CASE
WHEN YEAR(mn.Complete_Time_Schedule) = #{request.year}
THEN 1
ELSE 0
END) AS annualCompleteNum,
SUM(CASE
WHEN YEAR(mn.Complete_Records_Time_Schedule) = #{request.year}
THEN 1
ELSE 0
END) AS annualCompleteRecordsNum,
SUM(CASE
WHEN YEAR(mn.P_Remove_Time_Schedule) = #{request.year}
THEN 1
ELSE 0
END) AS annualPRemoveNum,
SUM(CASE
WHEN YEAR(mn.Account_Submit_Time_Schedule) = #{request.year}
THEN 1
ELSE 0
END) AS annualAccountSubmitNum,
SUM(CASE
WHEN YEAR(mn.Complete_Time_Finish) = #{request.year}
AND MONTH(mn.Complete_Time_Finish) <= #{request.month}
AND YEAR(mn.Complete_Time_Schedule) = #{request.year}
THEN 1
ELSE 0
END) AS completeNum,
SUM(CASE
WHEN YEAR(mn.Complete_Records_Time_Finish) = #{request.year}
AND MONTH(mn.Complete_Records_Time_Finish) <= #{request.month}
AND YEAR(mn.Complete_Records_Time_Schedule) = #{request.year}
THEN 1
ELSE 0
END) AS completeRecordsNum,
SUM(CASE
WHEN YEAR(mn.P_Remove_Time_Finish) = #{request.year}
AND MONTH(mn.P_Remove_Time_Finish) <= #{request.month}
AND YEAR(mn.P_Remove_Time_Schedule) = #{request.year}
THEN 1
ELSE 0
END) AS pRemoveNum,
SUM(CASE
WHEN YEAR(mn.Account_Submit_Time_Finish) = #{request.year}
AND MONTH(mn.Account_Submit_Time_Finish) <= #{request.month}
AND YEAR(mn.Account_Submit_Time_Schedule) = #{request.year}
THEN 1
ELSE 0
END) AS accountSubmitNum
FROM (SELECT *
FROM gantt_milestone_statistics mn
where mn.Complete_Time_Finish = (SELECT MAX(mn2.Complete_Time_Finish)
FROM gantt_milestone_statistics mn2
where mn2.p_id = mn.p_id)
) mn
LEFT JOIN
sys_department sd
ON sd.D_ID = mn.P_Competent_Department
${authSql}
and mn.Plan_Id IS NOT NULL

GROUP BY
sd.D_Name;

SELECT sd.D_Name AS competentDepartmentName,
'计划外完成' AS type,
SUM(IF(YEAR(mn.Complete_Time_Schedule) > #{request.year}, 1, 0)) AS annualCompleteNum,
SUM(IF(YEAR(mn.Complete_Records_Time_Schedule) > #{request.year}, 1, 0)) AS annualCompleteRecordsNum,
SUM(IF(YEAR(mn.P_Remove_Time_Schedule) > #{request.year}, 1, 0)) AS annualPRemoveNum,
SUM(IF(YEAR(mn.Account_Submit_Time_Schedule) > #{request.year}, 1, 0)) AS annualAccountSubmitNum,
SUM(IF(YEAR(mn.Complete_Time_Finish) = #{request.year}
AND MONTH(mn.Complete_Time_Finish) <= #{request.month}
AND YEAR(mn.Complete_Time_Schedule) > YEAR(mn.Complete_Time_Finish), 1,0))
AS completeNum,
SUM(IF(YEAR(mn.Complete_Records_Time_Finish) = #{request.year}
AND MONTH(mn.Complete_Records_Time_Finish) <= #{request.month}
AND YEAR(mn.Complete_Records_Time_Schedule) > YEAR(mn.Complete_Records_Time_Finish), 1, 0)
) AS completeRecordsNum,
SUM(IF(YEAR(mn.P_Remove_Time_Finish) = #{request.year}
AND MONTH(mn.P_Remove_Time_Finish) <= #{request.month}
AND YEAR(mn.P_Remove_Time_Schedule) > YEAR(mn.P_Remove_Time_Finish), 1, 0)
) AS pRemoveNum,
SUM(IF(YEAR(mn.Account_Submit_Time_Finish) = #{request.year}
AND MONTH(mn.Account_Submit_Time_Finish) <= #{request.month}
AND YEAR(mn.Account_Submit_Time_Schedule) > YEAR(mn.Account_Submit_Time_Finish), 1, 0)
) AS accountSubmitNum
FROM (SELECT *
FROM gantt_milestone_statistics mn
where mn.Complete_Time_Finish = (SELECT MAX(mn2.Complete_Time_Finish)
FROM gantt_milestone_statistics mn2
where mn2.p_id = mn.p_id)
) mn
LEFT JOIN
sys_department sd
ON sd.D_ID = mn.P_Competent_Department
${authSql}
and mn.Plan_Id IS NOT NULL

GROUP BY sd.D_Name;
